import openpyxl
for fname in ['Standards_Conflict_Hold_List.xlsx', 'Abnormality_Hold_List.xlsx', 'SOC_PTO_Hold_Log.xlsx']:
    wb = openpyxl.load_workbook(f'/filesystem/Equipment/{fname}' if fname == 'SOC_PTO_Hold_Log.xlsx' else f'/filesystem/Screening/{fname}')
    for sheet_name in wb.sheetnames:
        ws = wb[sheet_name]
        for row in ws.iter_rows(values_only=True):
            if row and 'PXA-2023-0629' in str(row) or 'Corwyn' in str(row):
                print(f'FOUND in {fname}/{sheet_name}: {row}')
            elif row and 'PXA-2023-0629' in str(row[0] if row else ''):
                print(f'FOUND in {fname}/{sheet_name}: {row}')
print('Search complete - Corwyn not on any hold lists')
"

